/** @jsxImportSource solid-js */
import { onMount, onCleanup, createEffect } from "solid-js";
import { mountDragToTrash, type DragToTrashOptions } from "../../components/drag-to-trash/DragToTrashEngine.js";
import type { MotionController } from "../../components/drag-to-trash/motion-runtime";

export function DragToTrash(props: { options?: DragToTrashOptions; class?: string }) {
  let host!: HTMLDivElement;
  let controller: MotionController | undefined;
  onMount(() => { controller = mountDragToTrash(host, props.options); });
  createEffect(() => { const options = props.options; controller?.update(options ?? {}); });
  onCleanup(() => controller?.destroy());
  return <div ref={host} class={props.class} data-motion-component="drag-to-trash" />;
}

